def gg(n,lol):
	ans = 0
	cur = 1
	lol2 = lol
	while(2*lol+1<=n):
		cur *= 2
		ans += cur
		lol = 2*lol+1
		lol2 *= 2
	if lol2*2 <= n:
		ans += n-lol2*2+1	
	return ans

