class BIT_RSQ():
    def __init__(self, n):
        self.n = n
        self.data = [0]*(n+2)

    def add(self, i, v):
        while i <= self.n:
            self.data[i] += v
            i += i & -i

    def sum(self, i):
        ret = 0
        while(i > 0):
            ret += self.data[i]
            i -= i & -i
        return ret

    def query(self, l, r):
        return self.sum(r) - self.sum(l-1)

    def lowerBound(self, w):
        if w <= 0: return 0
        x, k = 0, 2**self.n.bit_length()
        while k:
            if x+k <= self.n and self.data[x+k] < w:
                w -= self.data[x+k]
                x += k
            k >>= 1
        return x + 1

