def convert_to_binary(coef):
    res = []
    n = len(coef)
    carry = 0
    i = 0
    while i < n + 1000:
        if i >= n and not carry:
            break
        cur = carry
        if i < n:
            cur += coef[i]

        mod = cur % 2
        div = cur // 2
#        print(cur, div, mod)

        res.append(mod)

        carry = div

        i += 1
    return res, carry

