class Task:
    n = 0
    answer = ""

    def getData(self):
        self.n = int(input())

    def solve(self):
        n = self.n
        if n < 3:
            self.answer = "-1"
            return
        if n == 3:
            self.answer = "210"
            return
        tenRemainders = [1, 3, 2, 6, 4, 5]
        for x in range(0, 100):
            if (tenRemainders[(n - 1) % 6] + x * 10) % 7 == 0 and \
                    (1 + x // 10 + x % 10) % 3 == 0:
                self.answer = '1' + '0' * (n - 4)
                self.answer += '0' + str(x) if (x < 10) else str(x)
                self.answer += '0'
                return

    def printAnswer(self):
        print(self.answer)

