    return gcd(y, x % y)


memo = dict()
def brute(k, gc):
    if (k,gc) in memo:
        return memo[k,gc]
    if k == 0:
        if gc:
            return 1
        else:
            return 0
    ALL = 0
    for i in range(1, k + 1):
        ALL += brute(k-i,gcd(gc,i))
