    for _ in range(n):
        setK = set()
        while(len(setK) < 4):
            if(checkSet(setK,j) and not(len(setK) == 0 and j%3==0)):
                setK.add(j)
            j += 1
        sets.append(setK)
    maxV = 0
    for setK in sets:
        maxV = max(maxV,max(setK))
    print(maxV*k)
    for setK in sets:
        print(' '.join([str(x*k) for x in setK]))

